    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xA45372479FD2F9CDULL + 0xF9237D8F1B754291ULL);
