            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xF551AAF26188E457ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x4E49944BE3E5825DULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 50U)) & S_SALT1];
