            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xE698FD643CCCFB27ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0x1D4375A591C46CE6ULL) ^ aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 126U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x0419BACB0BAF8699ULL), 5U);
            //
            aIngress = RotL64(aOrbiterC, 41U) ^ aOrbiterD;
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterE, 28U));
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterG, 13U));
