            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ (((RotL64(aIngress, 3U) + aOrbiterE) + RotL64(aOrbiterC, 11U)) + aTwistWandererUpdateSaltC[((aIndex + 81U)) & S_SALT1]);
