            aOrbiterG = (((aWandererA + RotL64(aCross, 10U)) + RotL64(aCarry, 39U)) + 0xE3B748C5BEBBA86CULL) + aTwistOrbiterAssignSaltB[(((255U - aIndex) + 113U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x8EDB7C6A6B65BA72ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xC96B9D618A4BAEE2ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xB78DC8B44B42D417ULL), 53U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xFDADA03143A4A3BAULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x1D93CA5652739339ULL;
