            aCross = (RotL64(aHeartLaneA[((S_BLOCK1 - aIndex + 10321U)) & S_BLOCK1], 26U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 7594U)) & S_BLOCK1], 57U));
            aCross ^= RotL64(aWaterLaneA[((aIndex + 8366U)) & S_BLOCK1], 35U);
            aCross = TwistMix64::DiffuseA((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 11U) + RotL64(aCarry, 39U)) ^ (RotL64(aIngress, 27U) + RotL64(aCross, 54U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterC = (aWandererK + RotL64(aCross, 23U)) + 0x68545025AD86E17CULL;
            aOrbiterG = ((aWandererB + RotL64(aIngress, 13U)) + RotL64(aCarry, 13U)) + 0xFDEE68F6BC5F849DULL;
