            //
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 58U)) + 0x3013846E5C97AB78ULL;
            aOrbiterF = (((aWandererC + RotL64(aCross, 41U)) + RotL64(aCarry, 47U)) + 0x95FB9642155AFDD3ULL) + aTwistOrbiterAssignSaltA[((aIndex + 199U)) & S_SALT1];
            aOrbiterH = (aWandererD + RotL64(aIngress, 19U)) + 0x05C14901A035E81AULL;
            aOrbiterB = (aWandererE + RotL64(aScatter, 13U)) + 0x59A53B4E8259EA6EULL;
