            aOrbiterB = (aWandererD + RotL64(aCross, 58U)) + 0xF198BC1364B55387ULL;
            aOrbiterA = ((aWandererB + RotL64(aIngress, 21U)) + 0x229D29661A47F4F1ULL) + aTwistOrbiterAssignSaltC[((aIndex + 103U)) & S_SALT1];
            aOrbiterK = (aWandererE + RotL64(aPrevious, 43U)) + 0xEF5272AB5AE966B1ULL;
            aOrbiterD = (aWandererF + RotL64(aScatter, 3U)) + 0x9C0954A8E2134BABULL;
            aOrbiterJ = ((aWandererI + RotL64(aPrevious, 29U)) + RotL64(aCarry, 23U)) + 0x65DF321A50CE4BD7ULL;
            aOrbiterE = (aWandererG + RotL64(aIngress, 39U)) + 0x0AF976973195FAEFULL;
            aOrbiterF = ((aWandererK + RotL64(aScatter, 35U)) + RotL64(aCarry, 3U)) + 0x4BC09F723E32DD6DULL;
            aOrbiterI = (((aWandererJ + RotL64(aCross, 11U)) + RotL64(aCarry, 43U)) + 0x04F28CE6CD0F0F3EULL) + aTwistOrbiterAssignSaltA[(((255U - aIndex) + 31U)) & S_SALT1];
            aOrbiterH = (aWandererA + RotL64(aScatter, 50U)) + 0x4F0F491229CD46E3ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x1EA9A31AFC787735ULL;
