            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x297585596A759109ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x2E24B9E9F1E41184ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD27443C89196E88FULL), 23U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x0CE41C24ADE5FA9CULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xE5361176D061310EULL;
            aOrbiterF = RotL64((aOrbiterF * 0x590F129DA64DAB0DULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x84FE48B65B903D56ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0xAF3BAD32A4F4370EULL) ^ aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 109U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x03133A071FD49E93ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x7932E10ED2DC91D2ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xC1A8BA4AAB6B26DAULL;
            aOrbiterD = RotL64((aOrbiterD * 0xD4D3D6D8504C316FULL), 27U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0x4A1BF85C0AEA956DULL) + aTwistOrbiterUpdateSaltE[((aIndex + 190U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0x76211F55656FBB5DULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 223U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x9EAA5E79BF8CF1EBULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x6E4C76387A4DB78DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xF5CB052F5FBD9684ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x68D97663EEC96A23ULL), 51U);
