            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0xB08CE60D5089FA5AULL) + aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 9U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0xF6E752978D620838ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xC86F683E184F1CCFULL), 57U);
