            aWandererB = aWandererB ^ (((RotL64(aCross, 21U) + RotL64(aOrbiterD, 39U)) + aOrbiterH) + aTwistWandererUpdateSaltF[((aIndex + 180U)) & S_SALT1]);
            aWandererJ = aWandererJ + (((RotL64(aScatter, 53U) + aOrbiterJ) + RotL64(aOrbiterI, 11U)) + RotL64(aCarry, 35U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 5U) + aOrbiterF) + RotL64(aOrbiterJ, 43U));
