            aCarry = aCarry + (RotL64(aWandererE, 3U) ^ aWandererD);
            aCarry = aCarry + (RotL64(aWandererK, 58U) ^ aWandererG);
            aCarry = aCarry + (RotL64(aWandererB, 35U) ^ aWandererJ);
