            //
            aIngress = (RotL64(aWoodLaneA[((aIndex + 1443U)) & S_BLOCK1], 5U) ^ RotL64(aWoodLaneB[((aIndex + 935U)) & S_BLOCK1], 51U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 238U)) & W_KEY1], 35U) ^ RotL64(aFireLaneD[((aIndex + 3111U)) & S_BLOCK1], 20U));
