            aCross = (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 489U)) & S_BLOCK1], 46U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 698U)) & S_BLOCK1], 57U));
