            //
            aOrbiterC = ((aWandererH + RotL64(aIngress, 60U)) + RotL64(aCarry, 23U)) + 0x0C75D550595D0E82ULL;
            aOrbiterF = ((aWandererJ + RotL64(aCross, 13U)) + RotL64(aCarry, 51U)) + 0xD78F8BCB4EBEF70CULL;
            aOrbiterH = (aWandererD + RotL64(aPrevious, 29U)) + 0x9EF14040EF46C080ULL;
            aOrbiterI = (aWandererB + RotL64(aScatter, 35U)) + 0x640E64FD7971D9D0ULL;
            aOrbiterB = ((aWandererK + RotL64(aIngress, 51U)) + 0x7C5754BF86C0F6ECULL) + aTwistOrbiterAssignSaltA[(((255U - aIndex) + 237U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aCross, 43U)) + 0xBF3C25D783A82DD0ULL) + aTwistOrbiterAssignSaltC[((aIndex + 98U)) & S_SALT1];
            aOrbiterJ = ((aWandererC + RotL64(aPrevious, 19U)) + RotL64(aCarry, 39U)) + 0xA94476D245B2D73CULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xDEFB481F4D75D69FULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x6939BD52EE6B5C7CULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 26U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x7CBB23A23529C811ULL), 47U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x73F67A3AC40B296DULL) + aTwistOrbiterUpdateSaltE[(((255U - aIndex) + 50U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x7234591F535AD10FULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8A64510A199C1C0DULL), 53U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x6A42B5953BC1FC1CULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterI) ^ 0xAC5B567CFC94D809ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 235U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x6FC6F1F7D16E7ED9ULL), 5U);
            //
