            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x927E2EF06DDAB1CEULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x72F516192AB5657FULL;
            aOrbiterA = RotL64((aOrbiterA * 0x64574933AFBEFC3DULL), 11U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xD76448B5513591A8ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterJ) ^ 0x85F17A961B1E15B8ULL) ^ aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 91U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xC1103976918BDF91ULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x045BD676655C144AULL;
