            aWandererB = aWandererB + (((RotL64(aIngress, 53U) + RotL64(aOrbiterF, 35U)) + aOrbiterE) + RotL64(aCarry, 39U));
            aWandererD = aWandererD ^ (((RotL64(aPrevious, 6U) + RotL64(aOrbiterI, 6U)) + aOrbiterH) + aTwistWandererUpdateSaltF[(((255U - aIndex) + 250U)) & S_SALT1]);
            aWandererE = aWandererE + ((RotL64(aScatter, 21U) + aOrbiterB) + RotL64(aOrbiterJ, 39U));
            aWandererI = aWandererI ^ ((RotL64(aCross, 37U) + aOrbiterF) + RotL64(aOrbiterK, 43U));
            aWandererK = aWandererK + ((RotL64(aScatter, 29U) + aOrbiterK) + RotL64(aOrbiterD, 57U));
