            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xB85AE180C9652155ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0x296C529CEA932D2FULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 180U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xC95E1D32AF0EF5C7ULL), 3U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0xDF67324455F203E2ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 187U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x084B13590530C09EULL;
            aOrbiterG = RotL64((aOrbiterG * 0xADA4F39FBBD37DBDULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xC6966AB5273A943DULL;
