            aOrbiterJ = (((aWandererA + RotL64(aScatter, 5U)) + RotL64(aCarry, 21U)) + 0xBD3067324DFB727DULL) + aKeyRotateBOrbiterAssignSaltA[(((255U - aIndex) + 54U)) & S_SALT1];
