            aOrbiterE = ((aWandererD + RotL64(aCross, 27U)) + 0x8AE9B5A4EC2375BFULL) + aKeyRotateBOrbiterAssignSaltB[(((255U - aIndex) + 53U)) & S_SALT1];
            aOrbiterA = (aWandererF + RotL64(aPrevious, 11U)) + 0x7E36CC0A4412CE77ULL;
