            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x6383BD208DDB6638ULL) + aKeyRotateBOrbiterUpdateSaltF[(((255U - aIndex) + 187U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x97AFABD9AF396489ULL;
