            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x3322391F4DAD7F50ULL) + aKeyRotateBOrbiterUpdateSaltA[((aIndex + 95U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0xED54B6469EBA4BECULL;
