            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x9CC5109AF797DCD7ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0xA18FEED620CDC418ULL) ^ aKeyRotateBOrbiterUpdateSaltB[(((255U - aIndex) + 29U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x062C2BF7BA86998DULL), 19U);
